import json

lines = open('ios_crash.ips').readlines()
crash = json.loads(''.join(lines[1:]))

# Check for any additional fields with exception info
for key in ['legacyInfo', 'lastExceptionBacktrace', 'extMods']:
    if key in crash:
        val = crash[key]
        if isinstance(val, dict):
            print(f'{key}: {json.dumps(val, indent=2)[:500]}')
        elif isinstance(val, list):
            print(f'{key}: list with {len(val)} items')
        else:
            print(f'{key}: {str(val)[:200]}')

# Look for full 'asi' or 'reason' type info
print()
for key in sorted(crash.keys()):
    if key not in ['threads', 'usedImages', 'lastExceptionBacktrace']:
        val = crash[key]
        if isinstance(val, (str, int, float, bool)):
            print(f'{key}: {val}')
        elif isinstance(val, dict) and len(json.dumps(val)) < 500:
            print(f'{key}: {json.dumps(val)}')
        elif isinstance(val, list) and len(json.dumps(val)) < 500:
            print(f'{key}: {json.dumps(val)}')
        else:
            print(f'{key}: ({type(val).__name__}, len={len(val) if hasattr(val, \"__len__\") else \"?\"})') 
